function renderPlanetDetails(p,moons){$('#details').innerHTML=`<div class="details-kicker"><span>ДОСЬЕ ПЛАНЕТЫ</span><span>0${PLANETS.indexOf(p)+1} / 08</span></div><div class="latin">${p.latin}</div><h2>${p.name}</h2><span class="object-type">${p.type}</span><p class="description">${p.description}</p>${['neptune','uranus'].includes(p.id)?'<p class="fine">Цвет приближён к реконструкции Irwin et al. (2024). Это визуальная интерпретация, а не фотометрически калиброванный снимок.</p>':''}<div class="fact-grid"><div><small>ДИАМЕТР</small><strong>${p.diameter}<em>км</em></strong></div><div><small>ОТ СОЛНЦА · СРЕДНЕЕ</small><strong>${p.distance}<em>млн км</em></strong></div><div><small>ПЕРИОД ОБРАЩЕНИЯ</small><strong>${p.year}</strong></div><div><small>ВРАЩЕНИЕ ВОКРУГ ОСИ</small><strong>${p.day}</strong></div></div><div class="did-you-know"><h3>БЛИЖЕ К ОТКРЫТИЮ</h3><p>${p.fact}</p></div><div class="moon-title"><h3>Спутники</h3><span class="count">${moons.length} в каталоге</span></div>${moons.length?'<input class="moon-search" id="moon-search" type="search" placeholder="Найти спутник…" aria-label="Найти спутник"><label class="maps-filter"><input id="observed-only" type="checkbox">С картами миссий</label><div id="moon-list" class="moon-list"></div><div id="moon-card"></div><p class="fine">Снимок JPL · 16.11.2026<br>Орбиты и размеры условные. Поверхности: карты миссий или иллюстрация — см. карточку спутника.</p>':'<p class="empty">У этой планеты нет известных естественных спутников.</p>'}<a class="source" href="https://science.nasa.gov/${p.id}/" target="_blank" rel="noreferrer">Подробнее о планете · NASA ↗</a>`;if(moons.length){renderMoonList(moons);$('#observed-only').onchange=()=>$('#moon-search').dispatchEvent(new Event('input'));$('#moon-search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();renderMoonList(moons.filter(m=>(!$('#observed-only').checked||MOON_MAPS[moonKey(m)])&&[m.ru,m.name,m.designation].some(v=>v?.toLowerCase().includes(q))));});}}
function renderMoonList(moons){$('#moon-list').innerHTML=moons.length?moons.map(m=>`<button class="moon-row ${selectedMoon===moonKey(m)?'selected':''}" data-moon="${escape(moonKey(m))}"><span class="moon-dot"></span><span>${escape(moonName(m))}${m.ru&&m.name?`<small>${escape(m.name)}</small>`:''}</span><span class="map-badge ${MOON_MAPS[moonKey(m)]?'available':'missing'}" title="${MOON_MAPS[moonKey(m)]?'Есть карта по данным миссии':'Карта не подключена'}">${MOON_MAPS[moonKey(m)]?.hd?'HD':MOON_MAPS[moonKey(m)]?'Карта':'—'}</span><span class="go">↗</span></button>`).join(''):'<p class="empty">Спутник не найден. Попробуйте другое имя или обозначение.</p>';document.querySelectorAll('.moon-row').forEach(b=>b.onclick=()=>selectMoon(b.dataset.moon));}
function selectMoon(key){const obj=moonObjects.find(o=>moonKey(o.userData.moon)===key);if(!obj){const m=(catalog.planets[selectedPlanet.id]||[]).find(m=>moonKey(m)===key);showCatalogBody({name:moonName(m||{name:key}),parent:selectedPlanet.name,confirmed:true,reference:m?.designation||'',sourceObject:catalog.source});return;}selectedMoon=key;controls.minDistance=Math.max(.0005,obj.userData.radius*1.6);if(!state.moons){state.moons=true;$('#show-moons').checked=true;syncMoonsVisibility();}const m=obj.userData.moon,info=MOON_DETAILS[key];title('СПУТНИК · '+selectedPlanet.name.toUpperCase(),moonName(m),info?'Рассмотрите спутник и узнайте, чем он удивителен.':'Один из известных спутников в каталоге JPL.','СЛЕДОВАНИЕ ЗА СПУТНИКОМ');const target=obj.position.clone();const d=Math.max(.025,obj.userData.radius*4.4);if(!MOON_MAPS[key]){obj.geometry.dispose();obj.geometry=new THREE.SphereGeometry(obj.userData.radius,96,64);}fly(target.clone().add((['Miranda','Ariel','Umbriel','Titania','Oberon','Triton'].includes(key)?new THREE.Vector3(d*.35,-d*1.2,d*.35):new THREE.Vector3(d*.7,d*.5,d))),target);follow=obj;previousFollow.copy(obj.position);$('#moon-card').innerHTML=`<div class="moon-card"><div class="latin">СПУТНИК ПЛАНЕТЫ ${selectedPlanet.name.toUpperCase()}</div><h3>${escape(moonName(m))}</h3><p>${info?.text||'Естественный спутник. Его имя или временное обозначение включено в каталог JPL. Форма, размер и орбита в этой сцене условные; подробные физические характеристики здесь не приводятся.'}</p>${mapCaption(key)}${info?.diameter?`<p>Диаметр: <strong>${info.diameter} км</strong>${key==='Phobos'||key==='Deimos'||key==='Proteus'?' (средний)':''}</p>`:''}<p>${m.year?`Год открытия: ${escape(m.year)}`:'Известен с древности'}${m.designation?`<br>Обозначение: ${escape(m.designation)}`:''}</p><button id="back-planet">← Вернуться к планете</button></div>`;$('#back-planet').onclick=resetCamera;document.querySelectorAll('.moon-row').forEach(b=>b.classList.toggle('selected',b.dataset.moon===key));const existing=labels.find(l=>l.object===obj);if(!existing)addLabel(obj,moonName(m),()=>selectMoon(key));if(state.orbits&&!obj.userData.important){const old=moonGroup.getObjectByName('selected-orbit');if(old){moonGroup.remove(old);old.geometry.dispose();old.material.dispose();orbitLines=orbitLines.filter(o=>o!==old);}const line=addOrbit(obj.userData.orbit,moonGroup,0xefb284,.3,obj.userData.inc);line.name='selected-orbit';}if($('#titan-surface'))$('#titan-surface').onchange=e=>setTitanSurface(e.target.checked);mountSeasons();applySeason();addScaleNote();moonDetail.inspect(obj,key,MOON_MAPS[key]);$('#moon-card').scrollIntoView({block:'nearest',behavior:reducedMotion?'instant':'smooth'});}
function showBelt(id){showOverview();mode=id;setSelected(id);const b=BELTS[id];title('МАЛЫЕ ТЕЛА · '+(id==='asteroid'?'ВНУТРЕННЯЯ СИСТЕМА':'ВНЕШНЯЯ СИСТЕМА'),b.name,id==='asteroid'?'Каменные следы рождения планет.':'Ледяная окраина нашего космического дома.','ОБЛАСТЬ МАЛЫХ ТЕЛ');if(id==='asteroid')fly(new THREE.Vector3(0,75,95));$('#details').innerHTML=`<div class="details-kicker"><span>ОБЛАСТЬ СИСТЕМЫ</span><span>⠿</span></div><div class="latin">${b.latin}</div><h2>${b.name}</h2><span class="object-type">${b.type}</span><p class="description">${b.description}</p><div class="fact-grid"><div><small>ОТ СОЛНЦА · ПРИМЕРНО</small><strong>${b.range}<em>а.е.</em></strong></div><div><small>1 АСТРОНОМИЧЕСКАЯ ЕД.</small><strong>149,6<em>млн км</em></strong></div></div><div class="did-you-know"><h3>БЛИЖЕ К ОТКРЫТИЮ</h3><p>${b.fact}</p></div><div class="moon-title"><h3>Известные объекты</h3></div><p class="description">${b.objects}</p><p class="fine">Частицы обозначают область распространения тел. Их количество, плотность и размеры в сцене условные.</p><button class="cta" id="back-overview">Вся Солнечная система <span>↗</span></button><a class="source" href="${b.source}" target="_blank" rel="noreferrer">Подробнее о поясе · NASA ↗</a>`;$('#back-overview').onclick=showOverview;}
function resetCamera(){moonDetail.release();if(mode==='catalog'){fly(new THREE.Vector3(0,4,14));return;}if(mode==='planet'){controls.minDistance=4;selectedMoon=null;if($('#moon-card'))$('#moon-card').innerHTML='';title(`0${PLANETS.indexOf(selectedPlanet)+1} / ПЛАНЕТЫ СОЛНЕЧНОЙ СИСТЕМЫ`,selectedPlanet.name,'Мир и его спутники. Выберите объект, чтобы узнать больше.','В СИСТЕМЕ ПЛАНЕТЫ');fly(new THREE.Vector3(0,6.5,18));document.querySelectorAll('.moon-row').forEach(b=>b.classList.remove('selected'));mountSeasons();applySeason();}else{fly(mode==='asteroid'?new THREE.Vector3(0,75,95):overviewPosition());}}

function showCatalogBody(entry){
 mode='catalog';selectedPlanet=null;selectedMoon=null;overviewGroup.visible=false;disposeFocus();focusGroup.visible=true;follow=null;controls.minDistance=3.5;seasonLight.position.copy(lightDirection);
 const mapped=entry.officialName==='Charon';const body=new THREE.Mesh(new THREE.SphereGeometry(2.8,96,64),new THREE.MeshStandardMaterial({map:mapped?texture('charon-hd'):null,color:mapped?0xffffff:0x8e939a,roughness:1}));if(mapped)partialCoverage(body.material);focusGroup.add(body);installInspectionLight(focusGroup,inspectionLight);pickables=[];
 title('СПУТНИК · '+entry.parent,entry.name,'Нейтральная научная модель · поверхность не реконструирована','КАТАЛОГ · '+(entry.confirmed?'ПОДТВЕРЖДЁН':'КАНДИДАТ'));
 $('#details').innerHTML='<div class="latin">КАТАЛОЖНАЯ ЗАПИСЬ</div><h2>'+escape(entry.name)+'</h2><p class="description">Родительское тело: '+escape(entry.parent)+'</p><div class="map-provenance missing"><strong>Нейтральная модель</strong><p>Достоверная фотокарта не подключена. Шар обозначает объект: это не измеренная форма и не реальная текстура. Видимый размер и положение в этом отдельном просмотре условные.</p></div><p class="description">Статус JPL: '+(entry.confirmed?'подтверждён':'неподтверждённый кандидат')+'</p><p class="fine">'+escape(entry.reference||'')+'</p><a class="source" href="'+escape(entry.sourceObject||'https://ssd.jpl.nasa.gov/sb/sats.html')+'" target="_blank" rel="noreferrer">Данные и первоисточники · JPL ↗</a><p class="fine">Реальное фото поверхности в этой записи пока не подключено.</p>';
 if(mapped){$('#details').querySelector('.map-provenance').outerHTML='<div class="map-provenance"><strong>Харон · карта New Horizons / USGS · 8192×4096</strong><p>Реальная монохромная мозаика. Пустые области не заполнены выдуманным рельефом. Видимый размер в отдельном просмотре условный.</p><a class="source" href="https://astrogeology.usgs.gov/search/map/charon_new_horizons_lorri_mvic_global_mosaic_300m" target="_blank">Карта USGS ↗</a></div>';$('#scene-subtitle').textContent='Карта New Horizons · неполное покрытие';}const photo=missionPhoto(entry.officialName||entry.key||entry.name);if(photo){$('#details').querySelector('p.fine:last-child')?.remove();$('#details').insertAdjacentHTML('beforeend',photo);}$('#details').scrollTop=0;fly(new THREE.Vector3(0,4,14));
}

function updateMoons(){moonObjects.forEach(obj=>{const d=obj.userData,a=d.phase+simDays*d.speed*.12;obj.position.set(Math.cos(a)*d.orbit,Math.sin(a)*d.orbit*Math.sin(d.inc),Math.sin(a)*d.orbit*Math.cos(d.inc));});}
function syncMoonsVisibility(){if(moonGroup)moonGroup.visible=state.moons;pickables=mode==='planet'?[focusPlanet,...(state.moons?moonObjects:[])]:[...planetObjects,overviewGroup.userData.sun];if(!state.moons&&selectedMoon)resetCamera();}
function setPaused(value){paused=value;$('#pause').textContent=value?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',value?'Продолжить движение':'Приостановить движение');$('#pause').title=value?'Продолжить · Пробел':'Пауза · Пробел';}
function render(now){requestAnimationFrame(render);const delta=Math.min((now-previousTime)/1000,.05);previousTime=now;if(!paused){simDays+=delta*speed;const visualDelta=delta*Math.sqrt(speed);planetObjects.forEach(body=>{body.userData.mesh.rotation.y+=visualDelta*.09;});if(focusPlanet&&mode==='planet'){focusPlanet.userData.mesh.rotation.y+=visualDelta*.045*(selectedPlanet.id==='venus'||selectedPlanet.id==='uranus'?-1:1);if(focusPlanet.userData.clouds)focusPlanet.userData.clouds.rotation.y+=visualDelta*.052;}overviewGroup.userData.sun.rotation.y+=visualDelta*.02;overviewGroup.userData.belts.asteroid.rotation.y+=visualDelta*.005;overviewGroup.userData.belts.kuiper.rotation.y+=visualDelta*.002;}
 planetObjects.forEach(body=>{const d=body.userData,p=d.planet,a=d.phase+simDays/p.period*Math.PI*2;const orbit=realScale?planetKm[PLANETS.indexOf(p)]/overviewUnitKm:p.orbit;body.position.set(Math.cos(a)*orbit,0,Math.sin(a)*orbit);});if(mode==='planet')updateMoons();
 if(transition){if(follow){const move=follow.position.clone().sub(previousFollow);transition.to.add(move);transition.targetTo.add(move);}const t=Math.min((now-transition.start)/1100,1),e=1-Math.pow(1-t,3);camera.position.lerpVectors(transition.from,transition.to,e);controls.target.lerpVectors(transition.targetFrom,transition.targetTo,e);if(t===1)transition=null;}else if(follow){const move=follow.position.clone().sub(previousFollow);camera.position.add(move);controls.target.add(move);}if(follow)previousFollow.copy(follow.position);controls.autoRotate=autoOrbit&&!transition;controls.autoRotateSpeed=.35;controls.update();renderer.render(scene,camera);
 if(frame++%2===0){const w=renderer.domElement.clientWidth,h=renderer.domElement.clientHeight;labels.forEach(({object,el})=>{let visible=state.labels&&!cinematic;if(mode==='planet'&&object!==focusPlanet&&!state.moons)visible=false;object.getWorldPosition(temp);if(mode==='planet'&&object!==focusPlanet){const toward=temp.clone().sub(camera.position);const t=-camera.position.dot(toward)/toward.lengthSq();if(t>0&&t<1&&camera.position.clone().addScaledVector(toward,t).length()<3.3)visible=false;}const dist=temp.distanceTo(camera.position);temp.project(camera);if(temp.z>1||temp.z< -1||Math.abs(temp.x)>1.1||Math.abs(temp.y)>1.1)visible=false;if(follow&&object!==follow&&dist<2)visible=false;el.style.display=visible?'block':'none';if(visible){el.style.left=(temp.x*.5+.5)*w+'px';el.style.top=(-temp.y*.5+.5)*h+Math.max(18,object.userData.radius?object.userData.radius/dist*h/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))+12:18)+'px';}});}
}
function bindUI(){
 $('#illuminate').onclick=()=>{inspectionLight.value=inspectionLight.value?0:1;$('#illuminate').setAttribute('aria-pressed',String(!!inspectionLight.value));$('#illuminate').textContent=inspectionLight.value?'◐ Обычный свет':'☀ Осветить';toast(inspectionLight.value?'Равномерная подсветка для осмотра':'Восстановлено сезонное освещение');};

 $('#scale-mode').textContent=realScale?'Масштаб: реальный':'Масштаб: наглядный';
 $('#scale-mode').onclick=()=>{realScale=!realScale;location.hash=realScale?'real':'illustrative';location.reload();};

 $('#cinema').onclick=()=>{cinematic=!cinematic;document.body.classList.toggle('cinematic',cinematic);$('#cinema').setAttribute('aria-pressed',String(cinematic));};
 $('#auto-orbit').onclick=()=>{autoOrbit=!autoOrbit;$('#auto-orbit').setAttribute('aria-pressed',String(autoOrbit));};
 $('#zoom-in').onclick=()=>zoomCamera(.78);$('#zoom-out').onclick=()=>zoomCamera(1.28);
 $('#previous-planet').onclick=()=>stepPlanet(-1);$('#next-planet').onclick=()=>stepPlanet(1);
$('#planet-nav').innerHTML=PLANETS.map((p,i)=>`<button class="planet-button" data-planet="${p.id}"><span class="planet-mini" ${mini(p.texture)}></span><span>${p.name}</span><span class="planet-number">0${i+1}</span></button>`).join('');document.querySelectorAll('.planet-button').forEach(b=>b.onclick=()=>showPlanet(b.dataset.planet));document.querySelectorAll('.belt-button').forEach(b=>b.onclick=()=>showBelt(b.dataset.belt));$('#brand').onclick=()=>showOverview();$('#overview').onclick=()=>showOverview();$('#explore').onclick=()=>showOverview();$('#reset-camera').onclick=resetCamera;$('#top-view').onclick=()=>{const target=follow?follow.position.clone():new THREE.Vector3();const d=mode==='planet'?(selectedMoon?Math.max(1.2,follow.userData.radius*7):32):mode==='asteroid'?112:(realScale?1100:290);fly(target.clone().add(new THREE.Vector3(0,d,.01)),target);};$('#pause').onclick=()=>setPaused(!paused);$('#speed').oninput=e=>{speed=clockSpeeds[+e.target.value];$('#speed-label').textContent=fmt(speed)+'×';};$('#show-orbits').onchange=e=>{state.orbits=e.target.checked;document.body.classList.toggle('orbits-hidden',!state.orbits);orbitLines.forEach(l=>l.visible=state.orbits);};$('#show-labels').onchange=e=>{state.labels=e.target.checked;};$('#show-moons').onchange=e=>{state.moons=e.target.checked;syncMoonsVisibility();if(mode!=='planet')toast('Спутники видны при выборе планеты');};const dialog=$('#about-dialog');$('#about').onclick=$('#scale-info').onclick=()=>dialog.showModal();$('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Полный экран недоступен в этом окне');}};document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea')||dialog.open)return;if(e.code==='Space'){e.preventDefault();setPaused(!paused);}if(e.key==='Escape'){if(cinematic){cinematic=false;document.body.classList.remove('cinematic');$('#cinema').setAttribute('aria-pressed','false');}else showOverview();}if(e.key==='ArrowRight')stepPlanet(1);if(e.key==='ArrowLeft')stepPlanet(-1);});}
function zoomCamera(factor){transition=null;const offset=camera.position.clone().sub(controls.target);offset.setLength(THREE.MathUtils.clamp(offset.length()*factor,controls.minDistance,controls.maxDistance));camera.position.copy(controls.target).add(offset);}
function stepPlanet(direction){const i=selectedPlanet?PLANETS.indexOf(selectedPlanet):(direction>0?-1:0);showPlanet(PLANETS[(i+direction+8)%8].id);}

function addScaleNote(){installInspectionLight(focusGroup,inspectionLight);
 $('#distance-note')?.remove();const p=document.createElement('p');p.id='distance-note';p.className='distance-note';
 const obj=selectedMoon?moonObjects.find(o=>moonKey(o.userData.moon)===selectedMoon):null;
 p.textContent=realScale?'Реальный масштаб: размеры планеты и известных спутников согласованы с расстояниями. '+(obj?.userData.aKm?'Средний радиус орбиты: '+fmt(obj.userData.aKm)+' км от центра планеты. ':'')+'Круговые орбиты показывают средние радиусы JPL, а не текущие положения; ориентация орбит схематична. Спутники без орбитальных данных доступны в каталоге, но не размещены произвольно. Неизвестные размеры обозначены условными точками.':'Наглядный масштаб: тела увеличены, орбиты разведены с запасом, чтобы тела не пересекались.';
 (selectedMoon?$('#moon-card'):$('#details')).prepend(p);
}

function missionPhoto(key){const photo=MISSION_PHOTOS[key];return photo?'<figure class="mission-photo"><a href="./photos/'+photo.file+'" target="_blank"><img src="./photos/'+photo.file+'" alt="Реальный снимок '+escape(key)+'" loading="lazy"></a><figcaption>'+escape(photo.note)+' · '+escape(photo.credit)+'</figcaption><a class="source" href="'+photo.source+'" target="_blank" rel="noreferrer">Фотография и описание ↗</a></figure>':'';}
function mapCaption(key){return baseMapCaption(key)+missionPhoto(key);}
function baseMapCaption(key){
 const meta=MOON_MAPS[key];
 if(!meta)return '<div class="map-provenance missing"><strong>Реальная карта не подключена</strong><p>В проверенных коллекциях подходящая фотомозаика не найдена или не получена. Показана нейтральная модель без выдуманных кратеров. Это не доказательство отсутствия любых снимков спутника.</p><a class="source" href="./moon-texture-audit.json" target="_blank">Результат поиска по всему каталогу ↗</a></div>';
 const obj=moonObjects.find(o=>moonKey(o.userData.moon)===key);
 return '<div class="map-provenance">'+(meta.resolution?'<div class="map-quality" id="map-quality">'+(meta.infrared?'Инфракрасная карта · ':'Подробная карта · ')+meta.resolution+' px</div>':'<div class="map-quality limited">Ограниченная детализация исходной карты</div>')+'<strong>'+ (meta.infrared?'Доступна инфракрасная карта':'Карта по данным космической миссии')+'</strong><p>'+escape(meta.mission)+' · '+escape(meta.credit)+'. '+(meta.mono?'Монохромная мозаика. ':'')+(meta.note||'Обработанная фотомозаика; разрешение неодинаково, освещение и цвета в 3D приблизительные.')+(meta.partial?' Неснятые области показаны ровным нейтральным материалом. Для спутников Урана и Тритона начальный ракурс направлен на заснятое южное полушарие. Пустые области не являются деталями поверхности.':'')+'</p><a class="source" href="'+meta.source+'" target="_blank" rel="noreferrer">Источник карты ↗</a>'+(meta.infrared?'<label class="maps-filter"><input id="titan-surface" type="checkbox" '+(obj?.userData.titanSurface?'checked':'')+'>Поверхность под дымкой · ИК</label><p class="fine">Без переключателя — модель видимой атмосферной дымки. В ИК-режиме — реальные данные с условными цветами, без атмосферы.</p>':'')+'</div>';
}
function setTitanSurface(enabled){
 const body=moonObjects.find(o=>moonKey(o.userData.moon)==='Titan');if(!body)return;
 body.userData.titanSurface=enabled;
 body.material.map=enabled?texture('titan-infrared'):null;
 body.material.color.setHex(enabled?0xffffff:0xd2a667);body.material.needsUpdate=true;
 const haze=body.getObjectByName('titan-haze');if(haze)haze.visible=!enabled;
 toast(enabled?'Титан: инфракрасная мозаика · условные цвета':'Титан: видимая атмосферная дымка');
}

function addPoleLabels(){
 const r=focusPlanet.userData.radius;
 focusPlanet.userData.poleLabels=[1,-1].map((sign,i)=>{const point=new THREE.Object3D();point.position.set(0,sign*r*1.14,0);focusPlanet.userData.tilt.add(point);return addLabel(point,i?'Ю':'С',()=>{},'pole-label');});
}
function mountSeasons(){
 $('#season-panel')?.remove();
 if(mode!=='planet'||!selectedPlanet)return;
 const panel=document.createElement('section');panel.id='season-panel';panel.className='season-panel';panel.setAttribute('aria-label','Сезонные облики');
 panel.innerHTML='<div class="season-heading"><h3>Времена года</h3><select id="season-hemisphere" aria-label="Полушарие сезона"><option value="north">Северное полушарие</option><option value="south">Южное полушарие</option></select></div><div class="season-tabs" role="group" aria-label="Выбор времени года">'+SEASONS.map((s,i)=>'<button data-season="'+i+'" aria-pressed="'+(i===seasonIndex)+'"><span>'+s.icon+'</span>'+s.name+'</button>').join('')+'</div><button class="season-day" id="season-day">☀ Вид на дневную сторону</button><div class="season-status" id="season-status"></div><div class="season-hemispheres" id="season-hemispheres"></div><p id="season-note" class="season-note"></p><a class="source" id="season-source" target="_blank" rel="noreferrer">О сезонных изменениях ↗</a>';
 const host=selectedMoon?$('#moon-card'):$('#details');
 if(selectedMoon)host.append(panel);else{const anchor=$('#details .description');host.insertBefore(panel,anchor);}
 $('#season-hemisphere').value=seasonHemisphere;$('#season-day').onclick=viewSeasonDay;
 if(selectedPlanet.id==='earth'&&!selectedMoon){const label=document.createElement('label');label.className='clouds-option';label.innerHTML='<input type="checkbox" id="season-clouds" '+(seasonClouds?'checked':'')+'>Показать облака';panel.querySelector('.season-tabs').after(label);$('#season-clouds').onchange=e=>{seasonClouds=e.target.checked;applySeason();};}

 panel.querySelectorAll('[data-season]').forEach(b=>b.onclick=()=>{seasonIndex=+b.dataset.season;applySeason();});
 $('#season-hemisphere').onchange=e=>{seasonHemisphere=e.target.value;applySeason();};
}
function viewSeasonDay(){
 if(mode!=='planet')return;
 const body=selectedMoon?moonObjects.find(o=>moonKey(o.userData.moon)===selectedMoon):null;
 const target=body?body.position.clone():new THREE.Vector3();
 const distance=body?Math.max(.025,body.userData.radius*4.4):18;
 const offset=seasonLight.position.clone().normalize().multiplyScalar(distance);offset.y+=distance*.32;
 fly(target.clone().add(offset),target);
 if(body){follow=body;previousFollow.copy(body.position);}
}
function applySeason(){
 if(mode!=='planet'||!selectedPlanet)return;
 const p=selectedPlanet,selection=resolveSeason(seasonIndex,seasonHemisphere),physicalIndex=selection.north;
 const solarLongitude=[0,90,180,270][physicalIndex];
 const angle=[Math.PI/2,0,-Math.PI/2,Math.PI][physicalIndex];
 // Light stays in the orbital plane; the planet's spin axis remains fixed.
 seasonLight.position.set(-Math.cos(angle)*55,0,Math.sin(angle)*55);
 scene.traverse(o=>{if(o.material?.uniforms?.sunDirection)o.material.uniforms.sunDirection.value.copy(seasonLight.position).normalize();});
 if(p.id==='earth'){
  const map=texture('earth_'+SEASONS[physicalIndex].id+'?v=midseason');
  focusPlanet.userData.mesh.material.map=map;
  focusPlanet.userData.mesh.material.needsUpdate=true;if(focusPlanet.userData.clouds)focusPlanet.userData.clouds.visible=seasonClouds;
 }
 if(p.id==='mars'){
  const cap=focusPlanet.userData.seasonCaps,summer=Math.sin(THREE.MathUtils.degToRad(solarLongitude));
  cap.north.value=.9+summer*.055;cap.south.value=.9-summer*.055;
 }
 const panel=$('#season-panel');if(!panel)return;
 panel.querySelectorAll('[data-season]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.season===seasonIndex)));
 let note=SEASON_NOTES[p.id],status=SEASONS[seasonIndex].event+' · '+(seasonHemisphere==='north'?'север':'юг');
 let source='https://science.nasa.gov/helio-and-you-seasons-on-earth-mars-and-beyond/';
 if(p.id==='earth'){status=selection.month+' 2004 · месячная мозаика';source='https://science.nasa.gov/earth/earth-observatory/blue-marble-next-generation/base-map/';}
 if(selectedMoon){
  if(selectedMoon==='Titan'){
   note='Титан разделяет сезонный цикл Сатурна. Один сезон длится около 7,5 земных лет. Здесь показаны четыре положения в году Сатурна и модель освещения; четыре достоверные сезонные карты дымки не используются.';
   source='https://science.nasa.gov/mission/cassini/science/titan/';
  }else if(selectedMoon==='Moon'){
   note='У Луны наклон оси относительно плоскости орбиты вокруг Солнца мал: земной смены снежных и зелёных сезонов здесь нет. Переключатель обозначает сезон Земли и меняет направление солнечного света в сцене. Геометрия лунных сезонов и лунных фаз не рассчитана.';
   source='https://science.nasa.gov/moon/facts/';
  }else{
   note='Для этого спутника нет набора четырёх сезонных карт в атласе. Показан выбранный сезон родительской планеты и условное освещение спутника. Его собственные наклон оси, прецессия, затмения и сезонный климат не реконструируются; поверхность сохраняется.';
  }
  status='Год планеты '+p.name+' · '+SEASONS[seasonIndex].name.toLowerCase();
 }
 $('#season-status').textContent=status;$('#season-hemispheres').textContent='Север: '+SEASON_NAMES[selection.north].toLowerCase()+' · Юг: '+SEASON_NAMES[selection.south].toLowerCase();if(focusPlanet.userData.poleLabels){focusPlanet.userData.poleLabels[0].textContent='С · '+SEASON_NAMES[selection.north].toLowerCase();focusPlanet.userData.poleLabels[1].textContent='Ю · '+SEASON_NAMES[selection.south].toLowerCase();}
 $('#season-note').textContent=note;
 $('#season-source').href=source;
}

async function start(){try{realScale=location.hash!=='#illustrative';orbitalData=(await (await fetch('./orbit-distances.json')).json()).elements;const response=await fetch('./moons-catalog.json');if(!response.ok)throw new Error('Не удалось загрузить каталог спутников');catalog=await response.json();initScene();bindUI();mountFullCatalog(entry=>{if(entry.planet){showPlanet(entry.planet);selectMoon(entry.key);}else showCatalogBody(entry);});showOverview(true);if(reducedMotion)setPaused(true);$('#catalog-total').textContent=Object.values(catalog.planets).flat().length;$('#loading').hidden=true;requestAnimationFrame(render);}catch(error){console.error(error);$('#loading').innerHTML=`<p>Не удалось открыть 3D-модель.</p><p class="fine">${escape(error.message)}</p><button class="cta" onclick="location.reload()">Попробовать снова</button>`;}}
start();
